def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    rects = []

    # Propose dense rectangular regions of a non-background color.
    for color in set(v for row in grid for v in row) - {bg}:
        for r0 in range(h):
            for r1 in range(r0 + 1, h):
                for c0 in range(w):
                    for c1 in range(c0 + 1, w):
                        area = (r1 - r0 + 1) * (c1 - c0 + 1)
                        if area < 6:
                            continue
                        count = sum(
                            grid[r][c] == color
                            for r in range(r0, r1 + 1)
                            for c in range(c0, c1 + 1)
                        )
                        if count / area >= 0.60:
                            # Require the color to occur along every row and column.
                            if all(any(grid[r][c] == color for c in range(c0, c1 + 1))
                                   for r in range(r0, r1 + 1)) and \
                               all(any(grid[r][c] == color for r in range(r0, r1 + 1))
                                   for c in range(c0, c1 + 1)):
                                rects.append((area, count / area, color, r0, r1, c0, c1))

    rects.sort(reverse=True)
    chosen = []
    for area, density, color, r0, r1, c0, c1 in rects:
        # Ignore sub-rectangles of a region already identified.
        if any(color == col and r0 >= a and r1 <= b and c0 >= x and c1 <= y
               for col, a, b, x, y in chosen):
            continue
        chosen.append((color, r0, r1, c0, c1))

    out = [row[:] for row in grid]
    for color, r0, r1, c0, c1 in chosen:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                out[r][c] = color
    return out
